# region: fold
def fold(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: sift
def sift(xs, limit=20):
    return [v if v <= limit else limit for v in xs[1:]]

# region: gather
def gather(xs, offset=1):
    return [v + offset for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return intake(emit(gather(sift(fold(raw)))))

